//! Markdown editing operations. They work on plain strings and character
//! ranges so they are easy to test and independent of the UI.

use crate::highlight::{heading_level, list_marker_len};

/// A selection in character (not byte) indices, `start <= end`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Sel {
    pub start: usize,
    pub end: usize,
}

impl Sel {
    pub fn new(a: usize, b: usize) -> Self {
        Sel { start: a.min(b), end: a.max(b) }
    }
    pub fn caret(a: usize) -> Self {
        Sel { start: a, end: a }
    }
    pub fn is_empty(&self) -> bool {
        self.start == self.end
    }
}

pub fn c2b(s: &str, c: usize) -> usize {
    s.char_indices().nth(c).map(|(b, _)| b).unwrap_or(s.len())
}

pub fn b2c(s: &str, b: usize) -> usize {
    s[..b.min(s.len())].chars().count()
}

fn line_start(s: &str, b: usize) -> usize {
    s[..b].rfind('\n').map(|i| i + 1).unwrap_or(0)
}

fn line_end(s: &str, b: usize) -> usize {
    s[b..].find('\n').map(|i| b + i).unwrap_or(s.len())
}

/// Wrap the selection with `left`/`right` (e.g. `**`), or unwrap it if it is already wrapped.
pub fn toggle_wrap(text: &mut String, sel: Sel, left: &str, right: &str) -> Sel {
    let bs = c2b(text, sel.start);
    let be = c2b(text, sel.end);
    let (ll, rl) = (left.chars().count(), right.chars().count());
    let inner = &text[bs..be];
    if inner.len() >= left.len() + right.len() && inner.starts_with(left) && inner.ends_with(right) && !inner.is_empty() {
        let new_inner = inner[left.len()..inner.len() - right.len()].to_string();
        text.replace_range(bs..be, &new_inner);
        return Sel::new(sel.start, sel.end - ll - rl);
    }
    if text[..bs].ends_with(left) && text[be..].starts_with(right) {
        text.replace_range(be..be + right.len(), "");
        text.replace_range(bs - left.len()..bs, "");
        return Sel::new(sel.start - ll, sel.end - ll);
    }
    text.insert_str(be, right);
    text.insert_str(bs, left);
    Sel::new(sel.start + ll, sel.end + ll)
}

/// Apply `f` to every line touched by the selection.
/// For a caret, the caret keeps its place relative to the end of the line.
fn map_lines(text: &mut String, sel: Sel, f: impl Fn(usize, &str) -> String) -> Sel {
    let bs = c2b(text, sel.start);
    let mut be = c2b(text, sel.end);
    if be > bs && text[..be].ends_with('\n') {
        be -= 1;
    }
    let ls = line_start(text, bs);
    let le = line_end(text, be);
    let block = text[ls..le].to_string();
    let new_block: Vec<String> = block.split('\n').enumerate().map(|(i, l)| f(i, l)).collect();
    let new_block = new_block.join("\n");
    let ls_c = b2c(text, ls);
    let old_len = block.chars().count();
    let new_len = new_block.chars().count();
    text.replace_range(ls..le, &new_block);
    if sel.is_empty() {
        let from_end = (ls_c + old_len).saturating_sub(sel.start);
        let pos = (ls_c + new_len).saturating_sub(from_end).max(ls_c);
        Sel::caret(pos)
    } else {
        Sel::new(ls_c, ls_c + new_len)
    }
}

fn split_indent(l: &str) -> (&str, &str) {
    let n = l.len() - l.trim_start_matches([' ', '\t']).len();
    (&l[..n], &l[n..])
}

fn strip_heading(body: &str) -> &str {
    let n = body.chars().take_while(|c| *c == '#').count();
    if n > 0 && n <= 6 {
        body[n..].trim_start_matches(' ')
    } else {
        body
    }
}

/// Make the touched lines a heading of `level` (toggles off if already that level; 0 = paragraph).
pub fn set_heading(text: &mut String, sel: Sel, level: usize) -> Sel {
    map_lines(text, sel, |_, l| {
        let (ind, body) = split_indent(l);
        let cur = heading_level(l).unwrap_or(0);
        let plain = strip_heading(body);
        if level == 0 || cur == level {
            format!("{ind}{plain}")
        } else {
            format!("{ind}{} {plain}", "#".repeat(level))
        }
    })
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum LinePrefix {
    Bullet,
    Numbered,
    Task,
    Quote,
}

fn strip_list(body: &str) -> &str {
    match list_marker_len(body) {
        Some(n) => &body[n..],
        None => body,
    }
}

fn has_prefix(body: &str, kind: LinePrefix) -> bool {
    match kind {
        LinePrefix::Quote => body.starts_with('>'),
        LinePrefix::Task => {
            list_marker_len(body).is_some()
                && (body[2.min(body.len())..].starts_with("[ ]") || body[2.min(body.len())..].starts_with("[x]") || body[2.min(body.len())..].starts_with("[X]"))
        }
        LinePrefix::Bullet => {
            (body.starts_with("- ") || body.starts_with("* ") || body.starts_with("+ "))
                && !has_prefix(body, LinePrefix::Task)
        }
        LinePrefix::Numbered => {
            let d = body.chars().take_while(|c| c.is_ascii_digit()).count();
            d > 0 && (body[d..].starts_with(". ") || body[d..].starts_with(") "))
        }
    }
}

/// Toggle a list / quote prefix on every touched non-empty line.
pub fn toggle_prefix(text: &mut String, sel: Sel, kind: LinePrefix) -> Sel {
    let bs = c2b(text, sel.start);
    let be = c2b(text, sel.end);
    let ls = line_start(text, bs);
    let le = line_end(text, be.max(bs));
    let all_have = text[ls..le]
        .split('\n')
        .filter(|l| !l.trim().is_empty())
        .all(|l| has_prefix(split_indent(l).1, kind));
    let any_line = text[ls..le].split('\n').any(|l| !l.trim().is_empty());
    let counter = std::cell::Cell::new(0usize);
    map_lines(text, sel, |_, l| {
        let (ind, body) = split_indent(l);
        if body.trim().is_empty() && any_line {
            return l.to_string();
        }
        if all_have && any_line {
            let stripped = match kind {
                LinePrefix::Quote => body[1..].strip_prefix(' ').unwrap_or(&body[1..]),
                _ => strip_list(body),
            };
            return format!("{ind}{stripped}");
        }
        let base = match kind {
            LinePrefix::Quote => body,
            _ => strip_list(body),
        };
        let n = counter.get() + 1;
        counter.set(n);
        match kind {
            LinePrefix::Bullet => format!("{ind}- {base}"),
            LinePrefix::Numbered => format!("{ind}{n}. {base}"),
            LinePrefix::Task => format!("{ind}- [ ] {base}"),
            LinePrefix::Quote => format!("{ind}> {base}"),
        }
    })
}

/// Indent or outdent the touched lines by `unit` spaces.
pub fn indent_lines(text: &mut String, sel: Sel, unit: usize, outdent: bool) -> Sel {
    let pad = " ".repeat(unit);
    map_lines(text, sel, |_, l| {
        if outdent {
            let n = l.chars().take(unit).take_while(|c| *c == ' ').count();
            if n == 0 && l.starts_with('\t') {
                l[1..].to_string()
            } else {
                l[n..].to_string()
            }
        } else if l.is_empty() && !sel.is_empty() {
            String::new()
        } else {
            format!("{pad}{l}")
        }
    })
}

/// Replace the selection with `s`; returns a caret after it.
pub fn insert(text: &mut String, sel: Sel, s: &str) -> Sel {
    let bs = c2b(text, sel.start);
    let be = c2b(text, sel.end);
    text.replace_range(bs..be, s);
    Sel::caret(sel.start + s.chars().count())
}

/// Make sure the insertion point is on a fresh line with a blank line before it.
fn block_prefix(text: &str, at_byte: usize) -> &'static str {
    let before = &text[..at_byte];
    if before.is_empty() || before.ends_with("\n\n") {
        ""
    } else if before.ends_with('\n') {
        "\n"
    } else {
        "\n\n"
    }
}

/// Wrap the selection in a fenced code block (or insert an empty one).
pub fn code_block(text: &mut String, sel: Sel) -> Sel {
    let bs = c2b(text, sel.start);
    let be = c2b(text, sel.end);
    let body = text[bs..be].to_string();
    let pre = block_prefix(text, bs);
    let inner = if body.is_empty() { String::new() } else { format!("{}\n", body.trim_end_matches('\n')) };
    let block = format!("{pre}```\n{inner}```\n");
    text.replace_range(bs..be, &block);
    // caret right after the opening fence so a language can be typed
    Sel::caret(sel.start + pre.chars().count() + 3)
}

pub fn table(text: &mut String, sel: Sel) -> Sel {
    let bs = c2b(text, sel.start);
    let pre = block_prefix(text, bs);
    let t = "| Column | Column | Column |\n| :----- | :----: | -----: |\n| Cell   | Cell   | Cell   |\n| Cell   | Cell   | Cell   |\n";
    let s = format!("{pre}{t}");
    let start = sel.start + pre.chars().count() + 2;
    insert(text, sel, &s);
    Sel::new(start, start + 6)
}

pub fn rule(text: &mut String, sel: Sel) -> Sel {
    let bs = c2b(text, sel.start);
    let pre = block_prefix(text, bs);
    insert(text, sel, &format!("{pre}---\n\n"))
}

/// `[text](url)` around the selection, selecting the part to type next.
pub fn link(text: &mut String, sel: Sel, image: bool) -> Sel {
    let bs = c2b(text, sel.start);
    let be = c2b(text, sel.end);
    let label = text[bs..be].to_string();
    let bang = if image { "!" } else { "" };
    let url = if image { "image.png" } else { "https://" };
    if label.is_empty() {
        let placeholder = if image { "alt text" } else { "link text" };
        let s = format!("{bang}[{placeholder}]({url})");
        insert(text, sel, &s);
        let st = sel.start + bang.len() + 1;
        Sel::new(st, st + placeholder.chars().count())
    } else {
        let s = format!("{bang}[{label}]({url})");
        insert(text, sel, &s);
        let st = sel.start + bang.len() + label.chars().count() + 3;
        Sel::new(st, st + url.len())
    }
}

/// Continue lists and quotes when Enter is pressed. Returns the new caret if handled.
pub fn on_enter(text: &mut String, caret: usize) -> Option<usize> {
    let b = c2b(text, caret);
    let ls = line_start(text, b);
    let line = text[ls..b].to_string();
    let (ind, body) = split_indent(&line);
    let ind = ind.to_string();
    let (marker_len, next) = if let Some(n) = list_marker_len(body) {
        let marker = &body[..n];
        let next = if marker.starts_with(['-', '*', '+']) {
            let bullet = &marker[..1];
            if marker.contains('[') {
                format!("{bullet} [ ] ")
            } else {
                format!("{bullet} ")
            }
        } else {
            let d: String = marker.chars().take_while(|c| c.is_ascii_digit()).collect();
            let num: usize = d.parse().unwrap_or(0) + 1;
            let sep = marker.chars().nth(d.len()).unwrap_or('.');
            format!("{num}{sep} ")
        };
        (n, next)
    } else if body.starts_with("> ") || body == ">" {
        (body.len().min(2), "> ".to_string())
    } else {
        return None;
    };
    if body[marker_len..].trim().is_empty() {
        // empty item: end the list
        text.replace_range(ls..b, "");
        return Some(b2c(text, ls));
    }
    let ins = format!("\n{ind}{next}");
    text.insert_str(b, &ins);
    Some(caret + ins.chars().count())
}

fn is_table_line(l: &str) -> bool {
    l.trim_start().starts_with('|')
}

fn split_cells(l: &str) -> Vec<String> {
    let t = l.trim();
    let t = t.strip_prefix('|').unwrap_or(t);
    let t = if t.ends_with('|') && !t.ends_with("\\|") { &t[..t.len() - 1] } else { t };
    let mut cells = vec![];
    let mut cur = String::new();
    let mut prev = ' ';
    for c in t.chars() {
        if c == '|' && prev != '\\' {
            cells.push(cur.trim().to_string());
            cur.clear();
        } else {
            cur.push(c);
        }
        prev = c;
    }
    cells.push(cur.trim().to_string());
    cells
}

fn is_sep_cell(c: &str) -> bool {
    let t = c.trim();
    !t.is_empty() && t.trim_matches(':').chars().all(|c| c == '-') && t.contains('-')
}

/// Align the columns of a markdown table.
pub fn align_table(lines: &[&str]) -> Vec<String> {
    let rows: Vec<Vec<String>> = lines.iter().map(|l| split_cells(l)).collect();
    let cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);
    let sep_idx = rows.iter().position(|r| r.iter().all(|c| is_sep_cell(c)));
    let mut align = vec![(false, false); cols];
    if let Some(si) = sep_idx {
        for (i, c) in rows[si].iter().enumerate() {
            let t = c.trim();
            align[i] = (t.starts_with(':'), t.ends_with(':'));
        }
    }
    let mut width = vec![3usize; cols];
    for (ri, r) in rows.iter().enumerate() {
        if Some(ri) == sep_idx {
            continue;
        }
        for (i, c) in r.iter().enumerate() {
            width[i] = width[i].max(c.chars().count());
        }
    }
    rows.iter()
        .enumerate()
        .map(|(ri, r)| {
            let mut out = String::from("|");
            for i in 0..cols {
                let w = width[i];
                let cell = r.get(i).cloned().unwrap_or_default();
                if Some(ri) == sep_idx {
                    let (l, rr) = align[i];
                    let dashes = w - l as usize - rr as usize;
                    out.push(' ');
                    if l {
                        out.push(':');
                    }
                    out.push_str(&"-".repeat(dashes));
                    if rr {
                        out.push(':');
                    }
                    out.push_str(" |");
                } else {
                    let n = cell.chars().count();
                    let pad = w - n;
                    let (pl, pr) = match align[i] {
                        (true, true) => (pad / 2, pad - pad / 2),
                        (false, true) => (pad, 0),
                        _ => (0, pad),
                    };
                    out.push(' ');
                    out.push_str(&" ".repeat(pl));
                    out.push_str(&cell);
                    out.push_str(&" ".repeat(pr));
                    out.push_str(" |");
                }
            }
            out
        })
        .collect()
}

/// Align the table under the caret. Returns false if there is none.
pub fn format_table_at(text: &mut String, caret: usize) -> bool {
    let b = c2b(text, caret);
    let lines: Vec<&str> = text.split('\n').collect();
    let line_idx = text[..b].matches('\n').count();
    if !lines.get(line_idx).map(|l| is_table_line(l)).unwrap_or(false) {
        return false;
    }
    let mut a = line_idx;
    while a > 0 && is_table_line(lines[a - 1]) {
        a -= 1;
    }
    let mut z = line_idx;
    while z + 1 < lines.len() && is_table_line(lines[z + 1]) {
        z += 1;
    }
    let aligned = align_table(&lines[a..=z]);
    let mut out: Vec<String> = lines[..a].iter().map(|s| s.to_string()).collect();
    out.extend(aligned);
    out.extend(lines[z + 1..].iter().map(|s| s.to_string()));
    *text = out.join("\n");
    true
}

/// Tidy the whole document: trailing spaces, blank lines, bullets, tables,
/// spacing around headings. Code blocks are left untouched.
pub fn clean_document(text: &str) -> String {
    let lines: Vec<&str> = text.lines().collect();
    let mut out: Vec<String> = vec![];
    let mut in_fence = false;
    let mut i = 0;
    while i < lines.len() {
        let raw = lines[i];
        let t = raw.trim_start();
        if t.starts_with("```") || t.starts_with("~~~") {
            in_fence = !in_fence;
            out.push(raw.trim_end().to_string());
            i += 1;
            continue;
        }
        if in_fence {
            out.push(raw.to_string());
            i += 1;
            continue;
        }
        if is_table_line(raw) {
            let mut z = i;
            while z + 1 < lines.len() && is_table_line(lines[z + 1]) {
                z += 1;
            }
            out.extend(align_table(&lines[i..=z]));
            i = z + 1;
            continue;
        }
        // keep markdown hard breaks (exactly two trailing spaces)
        let trimmed = raw.trim_end();
        let mut line = if raw.ends_with("  ") && !raw.ends_with("   ") && !trimmed.is_empty() {
            format!("{trimmed}  ")
        } else {
            trimmed.to_string()
        };
        let (ind, body) = split_indent(&line);
        if (body.starts_with("* ") || body.starts_with("+ ")) && !crate::highlight::heading_level(body).is_some() {
            let (ind, rest) = (ind.to_string(), body[2..].to_string());
            line = format!("{ind}- {rest}");
        }
        let is_heading = heading_level(&line).is_some();
        if line.is_empty() {
            if out.last().map(|l: &String| l.is_empty()).unwrap_or(true) {
                i += 1;
                continue; // collapse blank runs and leading blanks
            }
        } else if is_heading && out.last().map(|l| !l.is_empty()).unwrap_or(false) {
            out.push(String::new());
        } else if !is_heading && i > 0 {
            if let Some(prev) = out.last() {
                if heading_level(prev).is_some() && !prev.is_empty() {
                    out.push(String::new());
                }
            }
        }
        out.push(line);
        i += 1;
    }
    while out.last().map(|l| l.is_empty()).unwrap_or(false) {
        out.pop();
    }
    let mut s = out.join("\n");
    s.push('\n');
    s
}

/// A heading in the outline.
#[derive(Clone, Debug)]
pub struct OutlineItem {
    pub level: usize,
    pub title: String,
    pub line: usize,
    pub char_pos: usize,
}

pub fn outline(text: &str) -> Vec<OutlineItem> {
    let mut v = vec![];
    let mut in_fence = false;
    let mut chars = 0;
    for (i, l) in text.split('\n').enumerate() {
        let t = l.trim_start();
        if t.starts_with("```") || t.starts_with("~~~") {
            in_fence = !in_fence;
        } else if !in_fence {
            if let Some(level) = heading_level(l) {
                let title = strip_heading(t).trim().trim_end_matches('#').trim().to_string();
                if !title.is_empty() {
                    v.push(OutlineItem { level, title, line: i, char_pos: chars });
                }
            }
        }
        chars += l.chars().count() + 1;
    }
    v
}

/// Word / character counts for the status bar.
pub fn word_count(text: &str) -> usize {
    text.split_whitespace()
        .filter(|w| w.chars().any(|c| c.is_alphanumeric()))
        .count()
}

/// (line, column), both 1-based, for a character index.
pub fn line_col(text: &str, caret: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for c in text.chars().take(caret) {
        if c == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

/// Character index where 0-based `line` starts.
pub fn line_to_char(text: &str, line: usize) -> usize {
    if line == 0 {
        return 0;
    }
    let mut n = 0;
    let mut chars = 0;
    for c in text.chars() {
        chars += 1;
        if c == '\n' {
            n += 1;
            if n == line {
                return chars;
            }
        }
    }
    chars
}

/// All matches of `query` as character ranges.
pub fn find_all(text: &str, query: &str, case_sensitive: bool, whole_word: bool) -> Vec<Sel> {
    if query.is_empty() {
        return vec![];
    }
    let (hay, needle) = if case_sensitive {
        (text.to_string(), query.to_string())
    } else {
        (text.to_lowercase(), query.to_lowercase())
    };
    // lowercase can change byte lengths for some scripts; fall back to exact search then
    let (hay, needle) = if hay.len() == text.len() { (hay, needle) } else { (text.to_string(), query.to_string()) };
    let mut out = vec![];
    let mut from = 0;
    let mut last_b = 0;
    let mut last_c = 0;
    while let Some(i) = hay[from..].find(&needle) {
        let b = from + i;
        let e = b + needle.len();
        let word_ok = !whole_word
            || (!text[..b].chars().next_back().map(is_word).unwrap_or(false)
                && !text[e..].chars().next().map(is_word).unwrap_or(false));
        if word_ok {
            let sc = last_c + text[last_b..b].chars().count();
            let ec = sc + text[b..e].chars().count();
            out.push(Sel::new(sc, ec));
            last_b = b;
            last_c = sc;
        }
        from = e.max(b + 1);
        while !hay.is_char_boundary(from) {
            from += 1;
        }
        if out.len() > 10_000 {
            break;
        }
    }
    out
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn wrap_and_unwrap() {
        let mut t = "hello world".to_string();
        let s = toggle_wrap(&mut t, Sel::new(0, 5), "**", "**");
        assert_eq!(t, "**hello** world");
        assert_eq!(s, Sel::new(2, 7));
        let s = toggle_wrap(&mut t, s, "**", "**");
        assert_eq!(t, "hello world");
        assert_eq!(s, Sel::new(0, 5));
    }

    #[test]
    fn headings_toggle() {
        let mut t = "Title\nbody".to_string();
        set_heading(&mut t, Sel::caret(2), 2);
        assert_eq!(t, "## Title\nbody");
        set_heading(&mut t, Sel::caret(4), 1);
        assert_eq!(t, "# Title\nbody");
        set_heading(&mut t, Sel::caret(4), 1);
        assert_eq!(t, "Title\nbody");
    }

    #[test]
    fn lists_toggle() {
        let mut t = "a\nb\nc".to_string();
        toggle_prefix(&mut t, Sel::new(0, 5), LinePrefix::Numbered);
        assert_eq!(t, "1. a\n2. b\n3. c");
        let len = t.chars().count();
        toggle_prefix(&mut t, Sel::new(0, len), LinePrefix::Numbered);
        assert_eq!(t, "a\nb\nc");
        toggle_prefix(&mut t, Sel::new(0, 5), LinePrefix::Task);
        assert_eq!(t, "- [ ] a\n- [ ] b\n- [ ] c");
    }

    #[test]
    fn enter_continues_lists() {
        let mut t = "- one".to_string();
        let c = on_enter(&mut t, 5).unwrap();
        assert_eq!(t, "- one\n- ");
        let c2 = on_enter(&mut t, c).unwrap();
        assert_eq!(t, "- one\n");
        assert_eq!(c2, 6);
        let mut n = "3. x".to_string();
        on_enter(&mut n, 4);
        assert_eq!(n, "3. x\n4. ");
    }

    #[test]
    fn table_alignment() {
        let out = align_table(&["|a|bb|", "|:-|-:|", "|ccc|d|"]);
        assert_eq!(out, vec!["| a   |  bb |", "| :-- | --: |", "| ccc |   d |"]);
    }

    #[test]
    fn clean_doc() {
        let s = clean_document("# T\ntext   \n\n\n\n* item\n```\n*  keep   \n```\n");
        assert_eq!(s, "# T\n\ntext\n\n- item\n```\n*  keep   \n```\n");
    }

    #[test]
    fn finds() {
        let f = find_all("Foo foo food", "foo", false, true);
        assert_eq!(f, vec![Sel::new(0, 3), Sel::new(4, 7)]);
        let f = find_all("é foo", "foo", true, false);
        assert_eq!(f, vec![Sel::new(2, 5)]);
    }
}

//! Rendered markdown preview: pulldown-cmark events -> a small block tree -> egui widgets.

use egui::text::{LayoutJob, TextFormat};
use egui::{Align, Color32, CornerRadius, FontFamily, FontId, Frame, Margin, RichText, Sense, Stroke, Ui};
use pulldown_cmark::{Alignment, CodeBlockKind, Event, Options, Parser, Tag, TagEnd};

use crate::highlight::Highlighter;
use crate::theme::{Palette, ThemeKind};

#[derive(Clone, Default, Debug)]
pub struct SpanStyle {
    pub strong: bool,
    pub emph: bool,
    pub strike: bool,
    pub code: bool,
    pub link: Option<String>,
    pub image: bool,
}

#[derive(Clone, Debug)]
pub struct Span {
    pub text: String,
    pub style: SpanStyle,
}

pub type Inline = Vec<Span>;

#[derive(Clone, Debug)]
pub struct Item {
    /// Some((checked, byte offset of the `[ ]` in the source)) for task items.
    pub task: Option<(bool, usize)>,
    pub blocks: Vec<Block>,
}

#[derive(Clone, Debug)]
pub enum Block {
    Heading(u8, Inline),
    Para(Inline),
    Quote(Vec<Block>),
    Code(String, String),
    List(Option<u64>, Vec<Item>),
    Rule,
    Table(Vec<Alignment>, Vec<Inline>, Vec<Vec<Inline>>),
    Html(String),
}

enum Container {
    Root(Vec<Block>),
    Quote(Vec<Block>),
    List(Option<u64>, Vec<Item>),
    Item(Option<(bool, usize)>, Vec<Block>),
}

struct Builder {
    stack: Vec<Container>,
    inline: Inline,
    in_text_block: bool,
    strong: u32,
    emph: u32,
    strike: u32,
    link: Vec<String>,
    image: u32,
    code: Option<(String, String)>,
    table: Option<(Vec<Alignment>, Vec<Inline>, Vec<Vec<Inline>>)>,
    row: Vec<Inline>,
    html: Option<String>,
}

impl Builder {
    fn push_block(&mut self, b: Block) {
        self.flush_tight();
        match self.stack.last_mut() {
            Some(Container::Root(v)) | Some(Container::Quote(v)) | Some(Container::Item(_, v)) => v.push(b),
            Some(Container::List(_, items)) => items.push(Item { task: None, blocks: vec![b] }),
            None => {}
        }
    }
    /// Text that arrived outside a paragraph (tight list items) becomes a paragraph.
    fn flush_tight(&mut self) {
        if !self.in_text_block && !self.inline.is_empty() {
            let inl = std::mem::take(&mut self.inline);
            match self.stack.last_mut() {
                Some(Container::Root(v)) | Some(Container::Quote(v)) | Some(Container::Item(_, v)) => v.push(Block::Para(inl)),
                _ => {}
            }
        }
    }
    fn text(&mut self, t: &str, code: bool) {
        let style = SpanStyle {
            strong: self.strong > 0,
            emph: self.emph > 0,
            strike: self.strike > 0,
            code,
            link: self.link.last().cloned(),
            image: self.image > 0,
        };
        self.inline.push(Span { text: t.to_string(), style });
    }
}

pub fn parse(src: &str) -> Vec<Block> {
    let mut opts = Options::empty();
    opts.insert(Options::ENABLE_TABLES);
    opts.insert(Options::ENABLE_STRIKETHROUGH);
    opts.insert(Options::ENABLE_TASKLISTS);
    opts.insert(Options::ENABLE_FOOTNOTES);
    let mut b = Builder {
        stack: vec![Container::Root(vec![])],
        inline: vec![],
        in_text_block: false,
        strong: 0,
        emph: 0,
        strike: 0,
        link: vec![],
        image: 0,
        code: None,
        table: None,
        row: vec![],
        html: None,
    };
    for (ev, range) in Parser::new_ext(src, opts).into_offset_iter() {
        match ev {
            Event::Start(tag) => match tag {
                Tag::Paragraph => {
                    b.flush_tight();
                    b.in_text_block = true;
                }
                Tag::Heading { .. } => {
                    b.flush_tight();
                    b.in_text_block = true;
                }
                Tag::BlockQuote(_) => {
                    b.flush_tight();
                    b.stack.push(Container::Quote(vec![]));
                }
                Tag::CodeBlock(kind) => {
                    b.flush_tight();
                    let lang = match kind {
                        CodeBlockKind::Fenced(l) => l.split_whitespace().next().unwrap_or("").to_string(),
                        CodeBlockKind::Indented => String::new(),
                    };
                    b.code = Some((lang, String::new()));
                }
                Tag::HtmlBlock => {
                    b.flush_tight();
                    b.html = Some(String::new());
                }
                Tag::List(start) => {
                    b.flush_tight();
                    b.stack.push(Container::List(start, vec![]));
                }
                Tag::Item => b.stack.push(Container::Item(None, vec![])),
                Tag::Table(al) => {
                    b.flush_tight();
                    b.table = Some((al, vec![], vec![]));
                }
                Tag::TableHead | Tag::TableRow => b.row.clear(),
                Tag::TableCell => {
                    b.inline.clear();
                    b.in_text_block = true;
                }
                Tag::Emphasis => b.emph += 1,
                Tag::Strong => b.strong += 1,
                Tag::Strikethrough => b.strike += 1,
                Tag::Link { dest_url, .. } => b.link.push(dest_url.to_string()),
                Tag::Image { .. } => b.image += 1,
                _ => {}
            },
            Event::End(tag) => match tag {
                TagEnd::Paragraph => {
                    b.in_text_block = false;
                    let inl = std::mem::take(&mut b.inline);
                    b.push_block(Block::Para(inl));
                }
                TagEnd::Heading(level) => {
                    b.in_text_block = false;
                    let inl = std::mem::take(&mut b.inline);
                    b.push_block(Block::Heading(level as u8, inl));
                }
                TagEnd::BlockQuote(_) => {
                    b.flush_tight();
                    if let Some(Container::Quote(v)) = b.stack.pop() {
                        b.push_block(Block::Quote(v));
                    }
                }
                TagEnd::CodeBlock => {
                    if let Some((lang, code)) = b.code.take() {
                        b.push_block(Block::Code(lang, code));
                    }
                }
                TagEnd::HtmlBlock => {
                    if let Some(h) = b.html.take() {
                        b.push_block(Block::Html(h));
                    }
                }
                TagEnd::List(_) => {
                    if let Some(Container::List(s, items)) = b.stack.pop() {
                        b.push_block(Block::List(s, items));
                    }
                }
                TagEnd::Item => {
                    b.flush_tight();
                    if let Some(Container::Item(task, blocks)) = b.stack.pop() {
                        if let Some(Container::List(_, items)) = b.stack.last_mut() {
                            items.push(Item { task, blocks });
                        }
                    }
                }
                TagEnd::TableCell => {
                    b.in_text_block = false;
                    let inl = std::mem::take(&mut b.inline);
                    b.row.push(inl);
                }
                TagEnd::TableHead => {
                    if let Some(t) = &mut b.table {
                        t.1 = std::mem::take(&mut b.row);
                    }
                }
                TagEnd::TableRow => {
                    if let Some(t) = &mut b.table {
                        t.2.push(std::mem::take(&mut b.row));
                    }
                }
                TagEnd::Table => {
                    if let Some((a, h, r)) = b.table.take() {
                        b.push_block(Block::Table(a, h, r));
                    }
                }
                TagEnd::Emphasis => b.emph = b.emph.saturating_sub(1),
                TagEnd::Strong => b.strong = b.strong.saturating_sub(1),
                TagEnd::Strikethrough => b.strike = b.strike.saturating_sub(1),
                TagEnd::Link => {
                    b.link.pop();
                }
                TagEnd::Image => b.image = b.image.saturating_sub(1),
                _ => {}
            },
            Event::Text(t) => {
                if let Some((_, code)) = &mut b.code {
                    code.push_str(&t);
                } else if let Some(h) = &mut b.html {
                    h.push_str(&t);
                } else {
                    b.text(&t, false);
                }
            }
            Event::Code(t) => b.text(&t, true),
            Event::Html(t) => {
                if let Some(h) = &mut b.html {
                    h.push_str(&t);
                }
            }
            Event::InlineHtml(t) => b.text(&t, true),
            Event::SoftBreak => b.text(" ", false),
            Event::HardBreak => b.text("\n", false),
            Event::Rule => b.push_block(Block::Rule),
            Event::TaskListMarker(checked) => {
                if let Some(Container::Item(task, _)) = b.stack.last_mut() {
                    *task = Some((checked, range.start));
                }
            }
            Event::FootnoteReference(r) => b.text(&format!("[{r}]"), false),
            _ => {}
        }
    }
    b.flush_tight();
    match b.stack.into_iter().next() {
        Some(Container::Root(v)) => v,
        _ => vec![],
    }
}

/// Paints the block tree. Returns the source byte offset of a task box the user clicked.
pub struct Renderer<'a> {
    pub hl: &'a Highlighter,
    pub theme: ThemeKind,
    pub size: f32,
    pub clicked_task: Option<usize>,
}

impl<'a> Renderer<'a> {
    fn pal(&self) -> Palette {
        Palette::get(self.theme)
    }

    fn inline_job(&self, inl: &Inline, size: f32, color: Color32, family: FontFamily, wrap: f32) -> LayoutJob {
        let p = self.pal();
        let mut job = LayoutJob::default();
        job.wrap.max_width = wrap;
        for s in inl {
            let st = &s.style;
            let mut f = TextFormat {
                font_id: FontId::new(size, family.clone()),
                color,
                ..Default::default()
            };
            if st.code {
                f.font_id = FontId::new(size * 0.9, FontFamily::Monospace);
                f.color = p.code;
                f.background = p.code_bg;
            }
            if st.strong {
                f.color = if self.theme == ThemeKind::Dark { Color32::WHITE } else { Color32::BLACK };
            }
            if st.emph {
                f.italics = true;
            }
            if st.strike {
                f.strikethrough = Stroke::new(1.0, p.dim);
                f.color = p.dim;
            }
            if st.link.is_some() {
                f.color = p.link;
                f.underline = Stroke::new(1.0, p.link.gamma_multiply(0.5));
            }
            if st.image {
                f.color = p.dim;
                f.italics = true;
            }
            job.append(&s.text, 0.0, f);
        }
        job
    }

    fn inline(&self, ui: &mut Ui, inl: &Inline, size: f32, color: Color32) {
        let job = self.inline_job(inl, size, color, FontFamily::Proportional, ui.available_width());
        let links: Vec<String> = inl.iter().filter_map(|s| s.style.link.clone()).collect();
        let resp = ui.add(egui::Label::new(job).wrap());
        if let Some(first) = links.first() {
            let resp = resp.on_hover_text(first.clone());
            if resp.clicked() && (first.starts_with("http://") || first.starts_with("https://")) {
                ui.ctx().open_url(egui::OpenUrl::new_tab(first));
            }
        }
    }

    pub fn blocks(&mut self, ui: &mut Ui, blocks: &[Block]) {
        for (i, b) in blocks.iter().enumerate() {
            if i > 0 {
                ui.add_space(self.size * 0.55);
            }
            self.block(ui, b);
        }
    }

    fn block(&mut self, ui: &mut Ui, b: &Block) {
        let p = self.pal();
        let size = self.size;
        match b {
            Block::Heading(level, inl) => {
                let scale = match level {
                    1 => 2.0,
                    2 => 1.6,
                    3 => 1.3,
                    4 => 1.12,
                    _ => 1.0,
                };
                ui.add_space(size * 0.35);
                let color = if *level <= 2 { p.text } else { p.heading };
                let mut inl = inl.clone();
                for s in &mut inl {
                    s.style.strong = s.style.strong || *level >= 5;
                }
                self.inline(ui, &inl, size * scale, color);
                if *level <= 2 {
                    let r = ui.available_rect_before_wrap();
                    ui.painter().hline(r.x_range(), r.top() + 1.0, Stroke::new(1.0, p.faint));
                    ui.add_space(4.0);
                }
            }
            Block::Para(inl) => self.inline(ui, inl, size, p.text),
            Block::Quote(inner) => {
                let resp = Frame::new()
                    .inner_margin(Margin { left: 14, right: 4, top: 2, bottom: 2 })
                    .show(ui, |ui| {
                        ui.style_mut().visuals.override_text_color = Some(p.quote);
                        let mut sub = Renderer { hl: self.hl, theme: self.theme, size: self.size, clicked_task: None };
                        sub.blocks(ui, inner);
                        if sub.clicked_task.is_some() {
                            self.clicked_task = sub.clicked_task;
                        }
                    });
                let r = resp.response.rect;
                ui.painter().vline(r.left() + 3.0, r.y_range(), Stroke::new(3.0, p.accent.gamma_multiply(0.7)));
            }
            Block::Code(lang, code) => {
                let job = self.hl.snippet_job(code.trim_end_matches('\n'), if lang.is_empty() { "txt" } else { lang }, size * 0.88, self.theme);
                Frame::new()
                    .fill(p.code_bg)
                    .corner_radius(CornerRadius::same(5))
                    .stroke(Stroke::new(1.0, p.border))
                    .inner_margin(Margin::same(10))
                    .show(ui, |ui| {
                        ui.set_width(ui.available_width());
                        if !lang.is_empty() {
                            ui.with_layout(egui::Layout::right_to_left(Align::TOP), |ui| {
                                ui.label(RichText::new(lang).small().color(p.dim));
                            });
                        }
                        egui::ScrollArea::horizontal()
                            .id_salt(code.as_ptr() as usize)
                            .show(ui, |ui| {
                                let mut job = job;
                                job.wrap.max_width = f32::INFINITY;
                                ui.add(egui::Label::new(job).extend());
                            });
                    });
            }
            Block::List(start, items) => {
                for (i, item) in items.iter().enumerate() {
                    ui.horizontal_top(|ui| {
                        ui.add_space(4.0);
                        let marker_w = size * 1.6;
                        if let Some((checked, off)) = item.task {
                            let mut c = checked;
                            let r = ui.add_sized([marker_w, size * 1.3], egui::Checkbox::without_text(&mut c));
                            if r.clicked() {
                                self.clicked_task = Some(off);
                            }
                        } else {
                            let m = match start {
                                Some(s) => format!("{}.", s + i as u64),
                                None => "•".to_string(),
                            };
                            ui.add_sized(
                                [marker_w, size * 1.3],
                                egui::Label::new(RichText::new(m).size(size).color(p.accent)),
                            );
                        }
                        ui.vertical(|ui| {
                            ui.spacing_mut().item_spacing.y = 2.0;
                            let mut sub = Renderer { hl: self.hl, theme: self.theme, size: self.size, clicked_task: None };
                            if let (Some((true, _)), [Block::Para(inl)]) = (item.task, item.blocks.as_slice()) {
                                let mut inl = inl.clone();
                                for s in &mut inl {
                                    s.style.strike = true;
                                }
                                sub.inline(ui, &inl, size, p.dim);
                            } else {
                                for (bi, b) in item.blocks.iter().enumerate() {
                                    if bi > 0 {
                                        ui.add_space(3.0);
                                    }
                                    sub.block(ui, b);
                                }
                            }
                            if sub.clicked_task.is_some() {
                                self.clicked_task = sub.clicked_task;
                            }
                        });
                    });
                }
            }
            Block::Rule => {
                ui.add_space(4.0);
                let r = ui.available_rect_before_wrap();
                ui.painter().hline(r.x_range(), r.top(), Stroke::new(1.5, p.faint));
                ui.add_space(6.0);
            }
            Block::Table(aligns, head, rows) => {
                Frame::new()
                    .stroke(Stroke::new(1.0, p.faint))
                    .corner_radius(CornerRadius::same(4))
                    .inner_margin(Margin::same(6))
                    .show(ui, |ui| {
                        egui::Grid::new(head.as_ptr() as usize)
                            .striped(true)
                            .spacing([18.0, 6.0])
                            .show(ui, |ui| {
                                for (ci, cell) in head.iter().enumerate() {
                                    let mut c = cell.clone();
                                    for s in &mut c {
                                        s.style.strong = true;
                                    }
                                    self.cell(ui, &c, aligns.get(ci).copied().unwrap_or(Alignment::None), p.heading);
                                }
                                ui.end_row();
                                for row in rows {
                                    for (ci, cell) in row.iter().enumerate() {
                                        self.cell(ui, cell, aligns.get(ci).copied().unwrap_or(Alignment::None), p.text);
                                    }
                                    ui.end_row();
                                }
                            });
                    });
            }
            Block::Html(h) => {
                ui.label(RichText::new(h.trim_end()).monospace().size(size * 0.85).color(p.dim));
            }
        }
    }

    fn cell(&self, ui: &mut Ui, inl: &Inline, a: Alignment, color: Color32) {
        let job = self.inline_job(inl, self.size, color, FontFamily::Proportional, f32::INFINITY);
        let layout = match a {
            Alignment::Right => egui::Layout::right_to_left(Align::Center),
            Alignment::Center => egui::Layout::top_down(Align::Center),
            _ => egui::Layout::left_to_right(Align::Center),
        };
        ui.with_layout(layout, |ui| {
            ui.add(egui::Label::new(job).sense(Sense::hover()));
        });
    }
}

/// Full HTML page for "Export as HTML".
pub fn to_html(src: &str, title: &str) -> String {
    let mut opts = Options::empty();
    opts.insert(Options::ENABLE_TABLES);
    opts.insert(Options::ENABLE_STRIKETHROUGH);
    opts.insert(Options::ENABLE_TASKLISTS);
    opts.insert(Options::ENABLE_FOOTNOTES);
    let mut body = String::new();
    pulldown_cmark::html::push_html(&mut body, Parser::new_ext(src, opts));
    let title = title.replace('<', "&lt;");
    format!(
